    """The least frequent color in the grid."""
    from collections import Counter
    return min(Counter(v for row in grid for v in row), key=lambda v: Counter(v for row in grid for v in row)[v])

def solid_rows(grid, color):
    """Row indices that are entirely the given color."""
    return {i for i, row in enumerate(grid) if set(row) == {color}}

def solid_cols(grid, color):
    """Column indices that are entirely the given color."""
    return {j for j in range(len(grid[0])) if all(row[j] == color for row in grid)}

def recolor_solid_lines(grid, color, new):
    """Cells of the given color lying in a row or column that is entirely that color become new."""
    sr, sc = solid_rows(grid, color), solid_cols(grid, color)
    return [[new if grid[i][j] == color and (i in sr or j in sc) else grid[i][j]
             for j in range(len(grid[0]))] for i in range(len(grid))]
